INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти интихоби дақиқи андозаи лӯла дар молотҳо</h2><p>Дар тарҳрезии системаҳои обёрӣи тампонӣ ва нақбӣ (ривер), яке аз марҳилаҳои мураккабтарин, вале муҳимтарин, интихоби андозаи муносиби лӯлаи асосӣ (Main Line) аст. Лӯлаҳои пластикӣ бо девори нозук ва пайвастшавии баъзан баъзан, бо сабаби чандирӣ ва муқовимати баланди кимиёвӣ, ҷойгузини маъмули лӯлаҳои қаҳраҳои қадимӣ гардидаанд. Андоза <strong>160 миллиметр</strong> яке аз андозаҳои бештар истифодашуда дар молотҳои бо андозаи миёна то калон мебошад, ки ҳам мувозинати хуб байни рафоби обу суръати моеъро таъмин мекунад ва ҳам аз нақари хараҷҳои насб ва нигоҳдорӣ ҷаҳатан мантиқӣ ба назар мерасад.</p><p>Бисёр деҳқонон ҳангоми хариди ин лӯла танҳо дар асоси фарза ва тахмин қарор медиҳанд; дар ҳоле ки ҳисобкунии дақиқи гидроликӣ барои пешгирӣ аз коҳиши зиёди фишор дар охири хат ва пурра нашудани об зарур аст. Ин мақола кӯшиш мекунад, ки бо шарҳи раванди ҳосилноксозӣ дар асоси талабот дар обёрӣ, шуморо бо мантиқи интихоби лӯлаи 160 шинос кунад.</p>\n\n\n\n<h2>Принсипҳои техникии ченкунӣ ва ҳисобкунии диаметри лӯлаи 160</h2><h3>Алоқамандии ҳаҷми умумии об бо диаметри лӯла</h3><p>Лӯлаи баъзани 160 миллиметр одатан барои интиқоли ҳаҷмҳо дар вобастагии 60 то 150 литр дар дақиқа тарҳрезӣ шудааст. Агар ҳаҷми баромади чашма ё захиравонаи шумо аз ин вобастагӣ камтар бошад, истифодаи лӯлаи 160 метавонад боиси паст шудани суръати моеъ аз ҳадди охирӣ (тақрибан 1 метр дар сония) гардад, ки дар натиҷа дар зарфи лӯла чорконӣ осеб меояд. Аз тарафи дигар, агар ҳаҷм хеле баланд бошад, суръати моеъ зиёд мешавад ва аҳамияти суратҳои лӯла боиси коҳиши шадиди фишор мегардад.</p><p>Барои ҳисоб, шумо бояд аввал интиқоли умумии шабакаи хокишавии худро ҷамъ оваред. Масалан, агар системаи шумо аз 20 шохба иборат бошад ва интиқоли ҳар як шохба 5 литр дар дақиқа бошад, интиқоли умумӣ 100 литр дар дақиқа аст. Ин ҳаҷми интиқол ҷонби 160-ро ба як имконияти мувофиқ табдил медиҳад, зеро суръати ҷараёнро дар диапазони бехатар (1.5 то 2.5 метр дар сония) нигоҳ медорад. Ҳисобкиши дақиқи интиқол баъзан лозим меояд, ки омилҳои зеринро таҳлил кунед: <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%B3%D9%88%DB%8C%D8%A7-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Модди бисёрзерида дар гектар</a> ва шиддати таъриши (сўнониш)-и ниҳол аст, то ки ҳоҷати анҷуми дақиқ муайян карда шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/اندازهگیری-لوله-نخدار-160-میلیمتر-برای-مزرعه-تصویر-شاخص.webp" alt="اندازه‌گیری لوله نخدار 160 میلیمتر برای مزرعه - تصویر 1"/><figcaption>product sizing farm irrigation ҷонби ресадор 160 миллиметр</figcaption></figure><h3>коэффисиенти ихтилош ва паст кардани фишор дар дарозии ҷонби</h3><p>Ҷонбиҳои PVC ва PE нисбат ба пӯлод ё лити қалъагӣ коэффисиенти ихтилоши гуногун доранд. Дар ҳисобкишҳои фаннӣ аз формулаи Дарси-Вайсбах (Darcy-Weisbach) истифода мебаранд. Барои ҷонби 160 миллиметрӣ, паст кардани фишор дар ҳар 100 метр ҷонби ба интиқоли ҷонби вобастагии бевосита дорад. Барои намуна, дар интиқоли 100 литр дар дақиқа, паст кардани фишор дар ҷонби тунук 160 тақрибан 0.5 то 0.8 метр сутуни об аст. Агар дарозии ҷонби асосии шумо аз 200 метр зиёд шавад, лозим аст, ки ҳисобкиши дақиқтари паст кардани фишоро иҷро кунед, то ки боварӣ пайдо кунед, ки фишор дар охири шохба барои коркунии фишинг ё пардаҳои хокишавӣ кофӣ аст.</p>\n\n\n\n<h2>Нуктаҳои амалӣ дар насб ва пайваст кардани ҷонби ресадор 160</h2><h3>Техники дурусти пайваст (Crimp vs. Threaded)</h3><p>Яке аз муқаррароти асосии лӯлаҳои 160 барои боғҳои хурд ва миёна, имконияти истифодаи пайвастҳои мурабатдор аст. Аммо нуқтаи заррӣ ин ҷост, ки «мурабат» танҳо дар пайвастҳои металлӣ ба пластикӣ ё пайвастҳои бозин барои сохтан истифода мешавад. Дар пайвастҳои лӯлаҳои пластикӣ ба ҳам, ҳанӯз ҳам аз пайвастҳои металлӣ ё пластикӣ бо печҳон (Crimping) истифода баред. Сиҳат кардани зиёди пайвастҳои бозини лӯлаи 160 боиси ҳассидани девораи лӯла дар натиҷаи фишори дарунӣ ва яхобарӣ мегардад. Дар ҷои пайвасти бозин аз навори талефлон ё чойби аквариум истифода баред, то аз омасиш пешгирӣ шавад, вале ҳаргез фишори механикиро ба худи лӯла ворид накунед.</p><h3>Идоракунии фишор дар шидати заминҳо</h3><p>Дushmanи калонтарини лӯлаи 160, паст шудани фишори ба далели шидати тез аст. Агар замини шумо шидат дошта бошад, лӯлаи 160 дар дашт (поён) бо фишори баландтари нисбат ба болошудӣ мувоҷеҳ мегардад. Ин метавонад боиси партофтани пайвастҳо ё омасиши об дар нуқтаҳои поёншуда бошад. Тавсия, насби вентили танбики фаҳр (PRV) дар оғози хатҳои асосӣ аст. Барои танзими беҳтарини система, дарки нурбоби чипи обкунӣ арзон ва чӣ тавр онҳо зери фишорҳои гуногун кор мекунанд зарур аст, то ба ин васила аз партофтани об дар нуқтаҳои фишорпалар пешгирӣ кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/اندازهگیری-لوله-نخدار-160-میلیمتر-برای-مزرعه-کاربرد-عملی.webp" alt="اندازه‌گیری لوله نخدار 160 میلیمتر برای مزرعه - تصویر 2"/><figcaption>product sizing farm irrigation лӯлаи мурабатдор 160 миллиметр</figcaption></figure>\n\n<h2>Муқоисаи корӣ бо андозаҳои муайян</h2><table><tr><th>Параметр</th><th>Лӯлаи 125 миллиметр</th><th>Лӯлаи 160 миллиметр</th><th>Лӯлаи 200 миллиметр</th></tr><tr><td>Шарофати тавсияшуда (литр/дақиқа)</td><td>40 то 80</td><td>60 то 120</td><td>120 то 200</th></tr><tr><td>Қабат ёфтани фишор (барои 100 метр - дар шарофати миёна)</td><td>Паст</td><td>Миёна</td><td>Хеле паст</td></tr><tr><td>Арзиши нисбӣ</td><td>1</td><td>1.5</td><td>2.2</td></tr><tr><td>Истифодаи мувозин</td><td>Захираҳои хурд/хатҳои иловагӣ</td><td>Захираҳои миёна/хати асосӣ</td><td>Деҳқониҳои калон / Хати асосӣ</td></tr></table><p>Чунинчунон ки дар jadval менамояд, лӯлаи 160 нуқтаи мувозинатро фароҳам меоварад. Интихоби лӯлаи 200 барои деҳқониҳое, ки ба саршилии зиёдатари аз 120 литр дар дақиқа бо паст нашави фишори ихтиёри ниёз доранд, дору мебошад. Аммо барои аксари деҳқониҳои кишвар, лӯлаи 160 бо системаи стандартии помпакунӣ интихоби арзонтар аст.</p>\n\n\n\n<h2>Саволҳои муқаррарӣ (FAQ)</h2><h3>Оё лӯлаи 160-сантиметрагӣ аз рӯи рафъофтононии рӯшноии офтоб тобовар аст?</h3><p>Бале, лӯлаҳои пилеэтилен (PE) ва пилевинохлорид (PVC) омудаги UV доранд. Аммо қаридагӣ дар офтоби табобатӣ ва ростӣ метавонад ба ивазшавии ранг ва зиёдшавии сабукшавии рӯи лӯла дар муддати тӯлонӣ боис шавад. Беҳтар аст ки лӯлаи асосиро дар каналҳои рой ё зери замин гузоред ё аз пӯломи муҳофизатии истифода баред.</p><h3>Фишори ками лӯлаи 160-сантиметрагӣ чанд аст?</h3><p>Фишори иҷротивои иростии лӯлаи 160 одатан байни 5 то 8 бар аст (вобаста ба толох ва сифати истеҳсол). Агар фишори чӯби шумо аз 8 бар зиёд бошад, бояд муҳолиқатон ва ҳатмӣ аст, ки аз як шир муҳаррики истифода баред, зеро фишори зиёдатии аз 10 бар метавонад ба заифшавии винтҳо ва озмокишӣ дар пайвастҳои лӯлаи 160 боис шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/اندازهگیری-لوله-نخدار-160-میلیمتر-برای-مزرعه-جزئیات-فنی.webp" alt="اندازه‌گیری لوله نخدار 160 میلیمتر برای مزرعه - تصویر 3"/><figcaption>product sizing farm irrigation лӯлаи 160-сантиметрагӣ</figcaption></figure><h3>Чӣ тавр фаҳмам, ки қубур дуруст танзимида шудааст?</h3><p>Баъд аз насб, системаро бо ҳаромадаи пурра иҷро кунед. Аз як манометр ё фишорчое боварӣ овранда истифода бурда, фишорро дар ибтидои хат ва ниҳоати хат (охирин ҳалқабур) андоза гиред. Агар камшавии фишор зиёда аз 10 то 15 фоиз бошад, бояд санҷед, ки оё диаметри қубур хурд аст ё дараҷаи майли зиёд аст. Ҳамчунин омӯзиши миқдори барди сабзӣ дар гектар ва заруратҳои обории он метавонад ба шумо кӯмак кунад, то ҳаромадаи дақиқтар барои тарҳрезии шабака дошта бошед.</p>\n\n<h2>Хулосабардорӣ ва тавсияҳои ниҳоӣ</h2><p>Истифодаи қубури рафранг 160 милметрӣ яке аз оқилонатарин қарорҳо дар тарҳрезии шабакаҳои обёрӣ барои молҳаҳо аст, ба шарте ки раванди андозгирии ва насб бо дақиқии муҳандисӣ иҷро шавад. Ин андоза барои молҳаҳои бо масоҳати 1 то 15 гектар мунтамоили баландро пешниҳод мекунад. Калиди муваффақият, мувофиқкунии ҳаромадаи баромадаи помпа ё чашмо бо диаметри қубур ва диққати майлҳои молҳа аст. Бо риояи принсипҳои зикршуда дар ин роҳнам ва истифодаи пайвастҳоҳои сифатнок, шумо метавонед аз камшавии фишорҳои ноқбул, нистакҳоҳои пинҳон ва харҷҳои таъмироти гаронбурҷ пешгирӣ кунед. Ҳамеша дар хотир доред, ки системаи обории хуб, асоси асосӣ барои зиёд кардани мизоҷи арзишнок дар гектар ва дигар маҳсулоти мебошад. Бо идоракунии дурусти об, шумо на танҳо харҷҳоро кам мекунед, балки сифати маҳсулотро низ кафолат медиҳед.</p>\n<p><strong>Маводеи алоқаманд:</strong> <a href="https://navar-abyari.ir/%D8%B4%D8%B1%D9%8A%D8%B7-%D8%A7%D9%84%D8%B1%D9%8A-%D8%A8%D8%A7%D9%84%D8%AA%D9%86%D9%82%D9%8A%D8%B7-%D9%81%D9%8A-%D9%82%D8%A7%D8%AF%D8%B3%DB%8C%D9%87/">D8B4D8B1D98AD8B7 D8A7D984D8B1D98A D8A8D8A7D984D8AAD986D982D98AD8B7 D981D98A D982D8A7D8AFD8B3DB8CD987</a>，“ <a href="https://navar-abyari.ir/clover-seed-per-hectare-guide-farmers/">clover seed per hectare guide farmers</a>，“ <a href="https://navar-abyari.ir/yield-of-dryland-barley-per-hectare-tips-increase-production/">yield of dryland barley per hectare tips increase production</a></p>','Мукаммалии рӯйхати ченҷ кардан ва насб кардани ҷӯбаи дасти 160 мм барои деҳқорон: аз ҳисобҳои техникавӣ то ҷузъиётҳои амалӣ','Интихоб ва андозагирии дурусти лӯлаҳои асосӣ, махсусан модели 160 миллиметр, арзишҳои дарозмуддат ва самаранокии системаро ҳал менамояд. Дар ин дастурамозири ихтисосӣ, бо принсипҳои гидроликӣ, усули пайвасткунии маҳрифтӣ ва роҳҳои кам кардани пастшавии фишор дар қасбаҳои калон шинос мешавед.','publish','closed','closed','mutalif-chennakiridan-dast160',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
